name = "geckoservo"
version = "0.0.1"
authors = ["The Servo Project Developers"]
license = "MPL-2.0"
edition = "2024"

[lib]
name = "geckoservo"
path = "lib.rs"

[features]
gecko_debug = ["style/gecko_debug", "nsstring/gecko_debug"]
